<template><AppShell><view class="page-heading"><text class="eyebrow">我的阅读 / READING ROOM</text><text class="page-title">让读过的故事，留在这里</text><text class="muted">本机书签、最近阅读与字号偏好。无需登录，仅保存在当前设备。</text></view><view class="reader-layout"><view><view class="section-heading compact"><view><text class="eyebrow">BOOKMARKS</text><text class="section-title">我的书签</text></view><text class="small">{{saved.length}} 段阅读</text></view><view class="reading-list"><button v-for="row in saved" :key="row.kind+row.id" @tap="go(row.kind,{id:row.id})"><view><text class="tag">{{row.kind==='person'?'人物':'事件'}}</text><text class="row-title">{{row.title}}</text></view><text>↗</text></button><view v-if="!saved.length" class="empty-paper"><text class="serif">把喜欢的片段，轻轻折一角</text><text class="muted">阅读人物或事件时，可添加本机书签。</text><button class="text-button" @tap="go('people')">去读一位人物 ↗</button></view></view><view class="section-heading compact"><view><text class="eyebrow">RECENTLY READ</text><text class="section-title">最近阅读</text></view><button v-if="recent.length" class="text-button" @tap="clear">清空记录</button></view><view class="reading-list"><button v-for="row in recent" :key="row.kind+row.id" @tap="go(row.kind,{id:row.id})"><view><text class="row-title">{{row.title}}</text><text class="small">{{row.kind==='person'?'人物档案':'历史片段'}}</text></view><text>↗</text></button><text v-if="!recent.length" class="muted">还没有阅读记录，故事从第一次打开开始。</text></view></view><view class="preference-card"><text class="eyebrow">阅读偏好</text><text class="block-title">让文字更适合你</text><text class="muted">调整人物简介与事件正文的字号。</text><view class="chips"><button :class="{active:size==='normal'}" @tap="change('normal')">标准字号</button><button :class="{active:size==='large'}" @tap="change('large')">大字号</button></view><text class="preference-sample" :class="{'reading-large':size==='large'}">山河有迹，史料为据。</text><view class="boundary-note"><text>书签和记录不会上传服务器，清除应用数据后可能丢失。账户同步收藏将在统一账户模块接入后提供。</text></view></view></view></AppShell></template>
<script setup>
import {ref} from 'vue';import {onShow} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import {go} from '../../lib/navigation.js';import {history,bookmarks,prefs,setSize,clearHistory} from '../../lib/reading.js'
const saved=ref([]),recent=ref([]),size=ref('normal');function refresh(){saved.value=bookmarks();recent.value=history();size.value=prefs().size}function change(value){setSize(value);size.value=value}function clear(){uni.showModal({title:'清空本机阅读记录',content:'书签会保留，最近阅读记录将被清空。',success:r=>{if(r.confirm){clearHistory();refresh()}}})}onShow(refresh)
</script>
